INSERT INTO "BlogPost" (id, title, slug, "metaTitle", "metaDescription", "featuredImageAlt", categoria, "publishedAt", "updatedAt", "createdAt", "authorId", excerpt, body, faqs, "relatedService", "readingTime", published) VALUES
(
  gen_random_uuid(),
  'PS5 Superaquecendo: Causas, Sintomas e Soluções Definitivas',
  'ps5-superaquecendo-causas-solucoes',
  'PS5 Superaquecendo? Causas, Sintomas e Como Resolver em 2026',
  'Seu PS5 está superaquecendo e desligando sozinho? Descubra as causas, sintomas e soluções definitivas para resolver o problema. Assistência técnica em Santa Maria RS.',
  'Console PS5 com ventilação obstruída por poeira',
  'Consoles',
  NOW(),
  NOW(),
  NOW(),
  'f573ec9e-ec58-4100-b634-4dc00ad8fbb1',
  'O superaquecimento do PS5 é um dos problemas mais comuns enfrentados por gamers. Neste guia completo, explicamos as causas, sintomas e todas as soluções definitivas para manter seu console funcionando perfeitamente.',
  '[{"type":"paragraph","children":[{"text":"O PlayStation 5 é um console potente, mas seu hardware de última geração gera muito calor. Quando o sistema de refrigeração não consegue dissipar esse calor adequadamente, o console começa a superaquecer, resultando em quedas de desempenho, travamentos e até desligamentos automáticos."}]},{"type":"heading","children":[{"text":"Por que o PS5 Superaquece?"}]},{"type":"paragraph","children":[{"text":"Existem várias razões pelas quais seu PS5 pode estar superaquecendo. A causa mais comum é o acúmulo de poeira nos dissipadores de calor e ventoinhas. O PS5 possui um design que, embora eficiente, pode acumular poeira rapidamente dependendo do ambiente onde está instalado."}]},{"type":"paragraph","children":[{"text":"Outra causa frequente é a má ventilação. O console precisa de pelo menos 10 centímetros de espaço livre em todas as direções para que o ar circule adequadamente. Colocar o PS5 dentro de um rack fechado ou muito próximo da parede é uma receita para o superaquecimento."}]},{"type":"paragraph","children":[{"text":"Problemas na pasta térmica também são comuns, especialmente em consoles mais antigos. A pasta térmica entre o processador e o dissipador de calor pode secar ou degradar com o tempo, reduzindo significativamente a eficiência da transferência de calor."}]},{"type":"heading","children":[{"text":"Sintomas de Superaquecimento"}]},{"type":"list","children":[{"text":"Ventoinha girando muito rápido e fazendo barulho excessivo"},{"text":"Console quente ao toque, especialmente na parte traseira"},{"text":"Queda de desempenho (FPS baixo) durante jogos pesados"},{"text":"Mensagem de aviso de temperatura elevada na tela"},{"text":"Desligamento automático sem aviso prévio"},{"text":"Travamentos e crashes frequentes durante sessões longas"}]},{"type":"heading","children":[{"text":"Soluções Definitivas"}]},{"type":"paragraph","children":[{"text":"A primeira e mais simples solução é a limpeza externa. Use um pano de microfibra levemente umedecido para limpar as entradas e saídas de ar. Um aspirador de pó com bocal estreito pode ajudar a remover poeira superficial das grades de ventilação."}]},{"type":"paragraph","children":[{"text":"Para uma limpeza mais profunda, é necessário abrir o console e limpar a ventoinha e o dissipador de calor. Este procedimento requer ferramentas adequadas e conhecimento técnico. Se você não tem experiência com manutenção de eletrônicos, recomendamos procurar uma assistência técnica especializada."}]},{"type":"paragraph","children":[{"text":"A troca da pasta térmica e dos thermal pads é a solução mais eficaz para problemas crônicos de superaquecimento. Utilizamos pastas térmicas de alta performance como Arctic MX-6 ou Thermal Grizzly Kryonaut, que oferecem condutividade térmica superior."}]},{"type":"paragraph","children":[{"text":"Também é importante verificar o posicionamento do console. Mantenha o PS5 em uma superfície plana, longe de fontes de calor como TVs e amplificadores, e com espaço adequado para ventilação."}]}]',
  '[{"question":"Como saber se meu PS5 está superaquecendo?","answer":"Os principais sinais são ventoinha barulhenta, console muito quente ao toque, queda de desempenho em jogos e desligamentos automáticos. Se você receber a mensagem de alerta de temperatura na tela, é sinal claro de superaquecimento."},{"question":"Posso limpar o PS5 sozinho?","answer":"A limpeza externa pode ser feita em casa com cuidado. Para limpeza interna, recomendamos assistência técnica especializada, pois abrir o console incorretamente pode danificar componentes sensíveis e anular a garantia."},{"question":"Quanto custa para resolver superaquecimento do PS5?","answer":"O valor varia conforme a gravidade. Uma limpeza completa com troca de pasta térmica custa entre R$150 e R$300. Entre em contato conosco para um orçamento personalizado."},{"question":"Superaquecimento pode danificar permanentemente o PS5?","answer":"Sim. O calor excessivo prolongado pode danificar componentes internos como o processador, a GPU e até soldas da placa-mãe. Quanto antes resolver, menores os danos."}]',
  '/servicos/limpeza-preventiva',
  7,
  true
);

INSERT INTO "BlogPost" (id, title, slug, "metaTitle", "metaDescription", "featuredImageAlt", categoria, "publishedAt", "updatedAt", "createdAt", "authorId", excerpt, body, faqs, "relatedService", "readingTime", published) VALUES
(
  gen_random_uuid(),
  'Quanto Custa Consertar um PS5? Guia de Preços 2026',
  'quanto-custa-consertar-ps5-guia-precos',
  'Quanto Custa Consertar um PS5 em 2026? Guia de Preços Atualizado',
  'Guia completo de preços para conserto de PS5 em 2026: HDMI, superaquecimento, fonte, leitor de disco. Orçamento transparente em Santa Maria RS.',
  'PS5 sendo reparado por técnico especializado',
  'Consoles',
  NOW(),
  NOW(),
  NOW(),
  'ee6b8943-cd39-4dbd-8921-dd35f7a55b34',
  'Saiba exatamente quanto custa cada tipo de reparo do PS5 em 2026. Preços atualizados para conserto de HDMI, superaquecimento, fonte e muito mais.',
  '[{"type":"paragraph","children":[{"text":"Seu PS5 quebrou e você está preocupado com o custo do conserto? Neste guia completo, detalhamos os preços de cada tipo de reparo em 2026 para que você possa tomar a melhor decisão."}]},{"type":"heading","children":[{"text":"Tabela de Preços de Reparos PS5"}]},{"type":"paragraph","children":[{"text":"Reparo da porta HDMI: R$250 a R$450. Este é um dos reparos mais comuns e o preço varia conforme o dano. Se apenas os pinos estão tortos, o custo é menor. Se a porta precisa ser totalmente substituída, o valor sobe."}]},{"type":"paragraph","children":[{"text":"Limpeza completa com troca de pasta térmica: R$150 a R$300. Inclui desmontagem completa, limpeza de todos os componentes, troca da pasta térmica do processador e thermal pads quando necessário."}]},{"type":"paragraph","children":[{"text":"Troca da fonte de alimentação: R$400 a R$700. A fonte do PS5 é um componente caro. O valor depende se usamos uma fonte original ou uma fonte compatível de alta qualidade."}]},{"type":"paragraph","children":[{"text":"Reparo do leitor de disco: R$300 a R$500. Inclui limpeza da lente, ajuste do mecanismo ou troca completa do leitor em casos mais graves."}]},{"type":"paragraph","children":[{"text":"Troca do SSD interno: R$250 a R$400 (apenas mão de obra). O valor do SSD é à parte e varia conforme a capacidade escolhida."}]},{"type":"heading","children":[{"text":"Por que os preços variam?"}]},{"type":"paragraph","children":[{"text":"O custo final depende de três fatores: gravidade do dano, disponibilidade de peças e se serão usadas peças originais ou compatíveis. Na Virtual Games, sempre apresentamos um orçamento detalhado antes de iniciar qualquer serviço."}]}]',
  '[{"question":"O orçamento é realmente grátis?","answer":"Sim! O diagnóstico e orçamento são totalmente gratuitos e sem compromisso. Você só paga se autorizar o serviço."},{"question":"Quanto tempo leva o conserto?","answer":"Reparos simples como limpeza levam 1 dia. Trocas de HDMI ou fonte levam de 2 a 3 dias. Reparos complexos podem levar até 5 dias."},{"question":"Usam peças originais?","answer":"Priorizamos peças originais Sony sempre que disponíveis. Quando não estão disponíveis, usamos peças compatíveis de alta qualidade com garantia."},{"question":"Oferecem garantia no serviço?","answer":"Sim! Todos os nossos reparos têm garantia de 90 dias. Se o mesmo problema voltar dentro deste período, reparamos sem custo adicional."}]',
  '/servicos/manutencao-ps5',
  5,
  true
);

INSERT INTO "BlogPost" (id, title, slug, "metaTitle", "metaDescription", "featuredImageAlt", categoria, "publishedAt", "updatedAt", "createdAt", "authorId", excerpt, body, faqs, "relatedService", "readingTime", published) VALUES
(
  gen_random_uuid(),
  'PS5 Não Liga: O Que Pode Ser e Como Resolver',
  'ps5-nao-liga-como-resolver',
  'PS5 Não Liga? Principais Causas e Soluções - Guia Completo',
  'Seu PS5 não liga? Descubra as causas mais comuns (fonte, superaquecimento, curto) e como resolver. Assistência técnica especializada em Santa Maria RS.',
  'PS5 que não liga com tela preta',
  'Consoles',
  NOW(),
  NOW(),
  NOW(),
  '2245169a-98be-45a0-a2f0-f4e57aa1b2ec',
  'PS5 não liga? Não entre em pânico. Listamos todas as causas possíveis e suas soluções, desde problemas simples que você resolve em casa até casos que precisam de assistência técnica.',
  '[{"type":"paragraph","children":[{"text":"Poucas coisas são mais frustrantes do que apertar o botão power do PS5 e... nada acontecer. Antes de entrar em desespero, saiba que muitas causas têm solução simples. Vamos listar todas as possibilidades em ordem da mais simples para a mais complexa."}]},{"type":"heading","children":[{"text":"Verificações Simples (faça primeiro)"}]},{"type":"list","children":[{"text":"Verifique se o cabo de força está bem conectado nas duas pontas"},{"text":"Teste outra tomada para descartar problemas elétricos"},{"text":"Verifique se o LED da fonte acende brevemente ao conectar"},{"text":"Tente ligar pelo controle e pelo botão físico do console"},{"text":"Remova todos os cabos USB e acessórios conectados"}]},{"type":"heading","children":[{"text":"Problemas na Fonte de Alimentação"}]},{"type":"paragraph","children":[{"text":"A fonte é o componente que mais falha quando o PS5 não liga. Se você não ouve nenhum som e nenhum LED acende, a fonte provavelmente queimou. Isso pode acontecer por picos de energia, raios ou simples desgaste do componente."}]},{"type":"paragraph","children":[{"text":"Um sinal típico de problema na fonte é quando o console emite um som de clique mas não liga. Isso indica que a fonte está tentando iniciar mas não consegue manter a tensão necessária."}]},{"type":"heading","children":[{"text":"Curto-circuito na Placa-Mãe"}]},{"type":"paragraph","children":[{"text":"Se o PS5 liga por alguns segundos e desliga imediatamente (luz azul pisca e apaga), pode ser um curto em algum componente da placa-mãe. Isso geralmente é causado por danos físicos, líquidos derramados ou falha de componentes."}]},{"type":"paragraph","children":[{"text":"Componentes comuns que entram em curto: capacitores da linha de alimentação, o próprio processador APU ou módulos de memória RAM. Este tipo de reparo requer diagnóstico com equipamentos especializados."}]}]',
  '[{"question":"Posso testar a fonte em casa?","answer":"Não recomendamos. Testar fontes requer equipamento específico e conhecimento técnico. Uma fonte com defeito pode causar choque elétrico. Traga para avaliação gratuita."},{"question":"PS5 queimou na tempestade, tem conserto?","answer":"Na maioria dos casos, sim! Geralmente apenas a fonte queima e pode ser substituída. Traga para diagnóstico - só cobramos se houver reparo."},{"question":"Quanto custa trocar a fonte do PS5?","answer":"Entre R$400 e R$700 dependendo se usamos fonte original ou compatível de alta qualidade. O diagnóstico é gratuito."}]',
  '/servicos/manutencao-ps5',
  5,
  true
);

INSERT INTO "BlogPost" (id, title, slug, "metaTitle", "metaDescription", "featuredImageAlt", categoria, "publishedAt", "updatedAt", "createdAt", "authorId", excerpt, body, faqs, "relatedService", "readingTime", published) VALUES
(
  gen_random_uuid(),
  'Drift no Controle PS5: Tem Conserto? Quanto Custa?',
  'drift-controle-ps5-conserto-custo',
  'Drift no Controle DualSense PS5: Tem Conserto? Preço e Solução',
  'Drift no analógico do controle PS5 DualSense? Saiba o que causa, se tem conserto, quanto custa o reparo e como resolver em Santa Maria RS.',
  'Controle DualSense PS5 com drift no analógico',
  'Controles e Acessórios',
  NOW(),
  NOW(),
  NOW(),
  '2245169a-98be-45a0-a2f0-f4e57aa1b2ec',
  'O temido drift no analógico do DualSense é um problema frustrante. Felizmente, TEM CONSERTO e não é necessário comprar um controle novo. Descubra as causas e quanto custa o reparo.',
  '[{"type":"paragraph","children":[{"text":"O drift no analógico é quando seu personagem se move sozinho ou a câmera gira sem você encostar no controle. Este problema afeta milhares de controles DualSense e pode arruinar completamente a experiência de jogo. Mas a boa notícia é que tem solução."}]},{"type":"heading","children":[{"text":"O que causa o drift no DualSense?"}]},{"type":"paragraph","children":[{"text":"O drift é causado principalmente pelo desgaste dos potenciômetros dentro dos módulos analógicos. Estes componentes são pequenas peças eletromecânicas que medem a posição do stick. Com o uso contínuo, o material interno se desgasta, causando leituras imprecisas."}]},{"type":"paragraph","children":[{"text":"Poeira e sujeira também são grandes vilões. Partículas minúsculas podem entrar no mecanismo do analógico e interferir nos contatos elétricos, causando movimentos fantasmas. Ambientes com muita poeira ou o hábito de comer enquanto joga aceleram este problema."}]},{"type":"heading","children":[{"text":"Tem conserto?"}]},{"type":"paragraph","children":[{"text":"SIM, tem conserto! Existem basicamente três níveis de reparo para drift no DualSense. O primeiro é a limpeza profunda dos potenciômetros com álcool isopropílico e ar comprimido. Este método resolve cerca de 40% dos casos de drift leve."}]},{"type":"paragraph","children":[{"text":"O segundo nível é a troca dos potenciômetros, que são componentes individuais dentro do módulo analógico. Este é um reparo mais técnico que requer soldagem de precisão. Resolve aproximadamente 90% dos casos."}]},{"type":"paragraph","children":[{"text":"O terceiro e mais definitivo é a troca completa do módulo analógico por um novo. Este procedimento substitui todo o mecanismo do stick, garantindo zero drift e a mesma sensação de um controle novo."}]},{"type":"heading","children":[{"text":"Quanto custa o reparo?"}]},{"type":"paragraph","children":[{"text":"Os preços variam conforme o tipo de reparo. Uma limpeza profissional custa entre R$60 e R$100. A troca dos potenciômetros fica entre R$100 e R$150 por analógico. A troca completa do módulo analógico custa entre R$130 e R$180 por stick."}]},{"type":"paragraph","children":[{"text":"Considerando que um DualSense novo custa entre R$350 e R$450, o reparo é sempre a opção mais econômica. Além disso, após o reparo com peças de qualidade, o controle pode durar ainda mais que um novo."}]}]',
  '[{"question":"Quanto tempo leva para consertar o drift?","answer":"A limpeza leva de 30 minutos a 1 hora. A troca de potenciômetros ou módulo leva de 1 a 2 horas. Na Virtual Games, muitos reparos são feitos no mesmo dia."},{"question":"O drift volta depois do conserto?","answer":"Quando feito corretamente com peças de qualidade, o reparo é duradouro. Nossos serviços têm garantia de 90 dias. Se voltar dentro deste período, reparamos sem custo adicional."},{"question":"Vale a pena consertar ou comprar um novo?","answer":"O conserto custa entre R$60 e R$180, enquanto um controle novo custa R$350+. O reparo é sempre a opção mais econômica, especialmente se o resto do controle está em bom estado."},{"question":"Consertam drift de outros controles também?","answer":"Sim! Trabalhamos com todos os controles: Xbox Series, Nintendo Switch (Joy-Con e Pro Controller), DualShock 4 (PS4) e controles de terceiros."}]',
  '/servicos/reparo-controle-drift',
  6,
  true
);
